import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type NodeDef = {label: string; mono?: boolean};
type Props = {headline: string; data: {nodes: NodeDef[]; branch: string[]; optional: string; interrupt: string; caption: string}; theme: Record<string, any>};
type Th = Record<string, any>;

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

const Chevron = (p: {x: number; y: number; dir: string; theme: Th; o: number}) => {
  const d = p.dir === 'd' ? `M${p.x - 9},${p.y - 11} L${p.x},${p.y} L${p.x + 9},${p.y - 11}` : `M${p.x - 11},${p.y - 9} L${p.x},${p.y} L${p.x - 11},${p.y + 9}`;
  return <path d={d} fill='none' stroke={p.theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={p.o} />;
};

const Box = (p: {x: number; y: number; w: number; h: number; label: string; t: number; active: number; theme: Th; fs: number; mono?: boolean; dashed?: boolean; split?: boolean}) => {
  const cut = p.label.indexOf(' ');
  const lines = p.split && cut > 0 ? [p.label.slice(0, cut), p.label.slice(cut + 1)] : [p.label];
  const dash = p.dashed ? '8 8' : undefined;
  return (
    <g opacity={p.t} transform={`translate(0 ${(1 - p.t) * 20})`}>
      <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={14} fill={p.theme.background} stroke={p.theme.muted} strokeWidth={2} strokeDasharray={dash} />
      <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={14} fill='none' stroke={p.theme.accent} strokeWidth={3} strokeDasharray={dash} opacity={p.active} />
      {lines.map((l, i) => (
        <text key={i} x={p.x + p.w / 2} y={p.y + p.h / 2 + (i - (lines.length - 1) / 2) * (p.fs + 6) + p.fs * 0.35} textAnchor='middle' fontSize={p.fs} fill={p.theme.text} fontFamily={p.mono ? 'monospace' : p.theme.font_body}>{l}</text>
      ))}
    </g>
  );
};

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 14, 14));
  const W = 1680, NW = 252, NH = 110, GAP = (W - 6 * NW) / 5, RY = 70, CY = RY + NH / 2;
  const cx = (i: number) => i * (NW + GAP) + NW / 2;
  const D0 = 30, SPAN = 200;
  const tAt = (x: number) => D0 + (SPAN * (x - cx(0))) / (cx(5) - cx(0));
  const dotX = interpolate(frame, [D0, D0 + SPAN], [cx(0), cx(5)], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const nodeT = (i: number) => (i === 0 ? ramp(frame, 6, 20) : ramp(frame, tAt(cx(i) - NW / 2) - 22, 20));
  const nodeA = (i: number) => clamp01((dotX - (cx(i) - NW / 2)) / 30);
  const dotO = ramp(frame, D0 - 8, 8);
  const pulse = 0.5 + 0.5 * Math.sin(frame / 8);
  const c3 = cx(3), LY = 260, LH = 100, LC = LY + LH / 2;
  const stem = ramp(frame, 150, 22);
  const oX = c3 - 100, cX = c3 + 140, cW = 280, mX = cX + cW + 40;
  const c1 = ramp(frame, 188, 12), c2 = ramp(frame, 214, 12);
  const iX = c3 - 420, iW = 280;
  const bl = d.branch;
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{flex: 1, display: 'flex', alignItems: 'center'}}>
        <svg width={W} height={500} viewBox={`0 0 ${W} 500`}>
          <path d={`M${cx(5)},${RY} V28 H${cx(0)} V${RY}`} fill='none' stroke={theme.muted} strokeWidth={2} strokeDasharray='10 10' opacity={0.8 * ramp(frame, 250, 24)} />
          <Chevron x={cx(0)} y={RY - 4} dir='d' theme={theme} o={ramp(frame, 270, 10)} />
          <text x={W / 2} y={38} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} stroke={theme.background} strokeWidth={26} paintOrder='stroke' opacity={ramp(frame, 266, 20)}>{d.interrupt}</text>
          {d.nodes.map((n, i) => (
            <Box key={i} x={cx(i) - NW / 2} y={RY} w={NW} h={NH} label={n.label} mono={n.mono} t={nodeT(i)} active={nodeA(i)} theme={theme} fs={size(32, theme)} />
          ))}
          {d.nodes.slice(0, -1).map((n, i) => {
            const x1 = cx(i) + NW / 2, x2 = cx(i + 1) - NW / 2;
            const fr = clamp01((dotX - x1) / (x2 - x1));
            return (
              <g key={i}>
                <line x1={x1} y1={CY} x2={x2} y2={CY} stroke={theme.muted} strokeWidth={2} opacity={0.4 * nodeT(i + 1)} />
                <line x1={x1} y1={CY} x2={x1 + (x2 - x1) * fr} y2={CY} stroke={theme.accent} strokeWidth={3} />
                <Chevron x={x2} y={CY} dir='r' theme={theme} o={fr >= 1 ? 1 : 0} />
              </g>
            );
          })}
          <circle cx={dotX} cy={CY} r={22 + 4 * pulse} fill={theme.accent} opacity={0.22 * dotO} />
          <circle cx={dotX} cy={CY} r={9} fill={theme.accent} opacity={dotO} />
          <line x1={c3} y1={RY + NH} x2={c3} y2={RY + NH + (LY - RY - NH) * stem} stroke={theme.accent} strokeWidth={3} />
          <path d={`M${c3},220 H${iX + iW / 2} V${LY}`} fill='none' stroke={theme.muted} strokeWidth={2} strokeDasharray='8 8' opacity={ramp(frame, 176, 24)} />
          <Box x={iX} y={LY} w={iW} h={LH} label={d.optional} t={ramp(frame, 184, 22)} active={0} theme={theme} fs={size(28, theme)} dashed split />
          <Box x={oX} y={LY} w={200} h={LH} label={bl[0]} t={ramp(frame, 166, 20)} active={stem >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} />
          <line x1={oX + 200} y1={LC} x2={oX + 200 + 40 * c1} y2={LC} stroke={theme.accent} strokeWidth={3} />
          <Chevron x={oX + 240} y={LC} dir='r' theme={theme} o={c1 >= 1 ? 1 : 0} />
          <Box x={cX} y={LY} w={cW} h={LH} label={bl[1]} t={ramp(frame, 196, 20)} active={c1 >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} split />
          <line x1={cX + cW} y1={LC} x2={cX + cW + 40 * c2} y2={LC} stroke={theme.accent} strokeWidth={3} />
          <Chevron x={mX} y={LC} dir='r' theme={theme} o={c2 >= 1 ? 1 : 0} />
          <Box x={mX} y={LY} w={200} h={LH} label={bl[2]} t={ramp(frame, 224, 20)} active={c2 >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} />
          <text x={0} y={470} fontSize={size(30, theme)} fill={theme.muted} opacity={ramp(frame, 300, 24)}>{d.caption}</text>
        </svg>
      </div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type Th = Record<string, any>;
type CardData = {title: string; items: string[]};
type Props = {headline: string; data: {surface: CardData; brain: CardData; down: string; up: string; modes: {name: string; note: string}[]; quote: string; emphasis: string}; theme: Th};

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

const Card = (p: {card: CardData; t0: number; frame: number; theme: Th}) => {
  const t = ramp(p.frame, p.t0, 22);
  return (
    <div style={{position: 'relative', width: 560, height: 340, boxSizing: 'border-box', padding: 40, border: `2px solid ${p.theme.muted}`, borderRadius: 14, opacity: t, transform: `translateY(${(1 - t) * 24}px)`}}>
      <div style={{position: 'absolute', inset: 0, borderRadius: 12, background: p.theme.text, opacity: 0.05}} />
      <div style={{position: 'relative', fontFamily: p.theme.font_heading, fontWeight: p.theme.heading_weight, fontSize: size(48, p.theme), letterSpacing: '-0.02em', marginBottom: 28}}>{p.card.title}</div>
      {p.card.items.map((it, i) => {
        const q = ramp(p.frame, p.t0 + 14 + i * 8, 18);
        return (
          <div key={i} style={{position: 'relative', display: 'flex', alignItems: 'center', gap: 20, marginTop: 18, fontSize: size(34, p.theme), color: p.theme.body, opacity: q, transform: `translateX(${(1 - q) * -16}px)`}}>
            <span style={{width: 18, height: 3, background: p.theme.accent}} />
            {it}
          </div>
        );
      })}
    </div>
  );
};

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 14, 14));
  const a1 = ramp(frame, 70, 28), a2 = ramp(frame, 98, 28);
  const slide = ramp(frame, 170, 22);
  const words = d.quote.split(' ');
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', gap: 56}}>
        <div style={{display: 'flex', alignItems: 'center'}}>
          <Card card={d.surface} t0={10} frame={frame} theme={theme} />
          <svg width={560} height={340} viewBox='0 0 560 340'>
            <line x1={30} y1={120} x2={30 + 500 * a1} y2={120} stroke={theme.accent} strokeWidth={3} />
            <path d='M519,109 L530,120 L519,131' fill='none' stroke={theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={a1 >= 1 ? 1 : 0} />
            <text x={280} y={90} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} opacity={ramp(frame, 76, 20)}>{d.down}</text>
            <line x1={530} y1={240} x2={530 - 500 * a2} y2={240} stroke={theme.accent} strokeWidth={3} />
            <path d='M41,229 L30,240 L41,251' fill='none' stroke={theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={a2 >= 1 ? 1 : 0} />
            <text x={280} y={290} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} opacity={ramp(frame, 104, 20)}>{d.up}</text>
          </svg>
          <Card card={d.brain} t0={30} frame={frame} theme={theme} />
        </div>
        <div style={{position: 'relative', display: 'flex', width: 840, height: 110, boxSizing: 'border-box', border: `2px solid ${theme.muted}`, borderRadius: 55, opacity: ramp(frame, 130, 20)}}>
          <div style={{position: 'absolute', top: 5, left: 5 + 414 * slide, width: 414, height: 96, boxSizing: 'border-box', border: `3px solid ${theme.accent}`, borderRadius: 48, overflow: 'hidden'}}>
            <div style={{position: 'absolute', inset: 0, background: theme.accent, opacity: 0.14}} />
          </div>
          {d.modes.map((m, i) => (
            <div key={i} style={{position: 'relative', flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
              <div style={{fontFamily: 'monospace', fontSize: size(30, theme), color: theme.text}}>{m.name}</div>
              <div style={{fontSize: size(28, theme), color: theme.muted}}>{m.note}</div>
            </div>
          ))}
        </div>
        <div style={{display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 16, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(60, theme), letterSpacing: '-0.02em'}}>
          {words.map((w, i) => {
            const q = ramp(frame, 190 + i * 4, 16);
            const hot = w.replace(/[.,!?]/g, '') === d.emphasis;
            return <span key={i} style={{color: hot ? theme.accent : theme.text, opacity: q, transform: `translateY(${(1 - q) * 18}px)`}}>{w}</span>;
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type Th = Record<string, any>;
type Props = {headline: string; data: {rows: string[]; commands: string[]; closing: string; note: string}; theme: Th};

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

const Lock = (p: {c: number; theme: Th}) => (
  <svg width={64} height={84} viewBox='0 0 64 84'>
    <path d='M18,42 V30 a14,14 0 0 1 28,0 V42' transform={`translate(0 ${-14 * (1 - p.c)})`} fill='none' stroke={p.c > 0.5 ? p.theme.accent : p.theme.muted} strokeWidth={4} strokeLinecap='round' />
    <rect x={8} y={42} width={48} height={34} rx={6} fill='none' stroke={p.theme.text} strokeWidth={3} />
    <circle cx={32} cy={59} r={4.5} fill={p.theme.accent} opacity={p.c} />
  </svg>
);

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 30, 30));
  const starts = [58, 98];
  const counts = d.commands.map((c, i) => Math.max(0, Math.min(c.length, Math.floor((frame - starts[i]) * 1.5))));
  const typing = counts[1] > 0 ? 1 : 0;
  const blink = frame % 30 < 18 ? 1 : 0;
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 64}}>
        <div style={{display: 'flex', gap: 60, alignItems: 'center'}}>
          <div style={{width: 820, display: 'flex', flexDirection: 'column', gap: 28}}>
            {d.rows.map((r, i) => {
              const t = ramp(frame, 10 + i * 14, 20);
              const c = ramp(frame, 30 + i * 14, 14);
              return (
                <div key={i} style={{display: 'flex', alignItems: 'center', gap: 32, padding: '20px 32px', border: `2px solid ${theme.muted}`, borderRadius: 14, fontSize: size(38, theme), opacity: t, transform: `translateX(${(1 - t) * -28}px)`}}>
                  <Lock c={c} theme={theme} />
                  {r}
                </div>
              );
            })}
          </div>
          <div style={{width: 800, boxSizing: 'border-box', border: `2px solid ${theme.muted}`, borderRadius: 14, overflow: 'hidden', opacity: ramp(frame, 34, 22), transform: `translateY(${(1 - ramp(frame, 34, 22)) * 24}px)`}}>
            <div style={{display: 'flex', gap: 10, padding: '16px 22px', borderBottom: `2px solid ${theme.muted}`}}>
              {[0, 1, 2].map((k) => <span key={k} style={{width: 14, height: 14, borderRadius: 7, background: theme.muted, opacity: 0.6}} />)}
            </div>
            <div style={{padding: '36px 36px 44px', fontFamily: 'monospace', fontSize: size(30, theme), lineHeight: 1.9}}>
              {d.commands.map((c, i) => (
                <div key={i} style={{display: 'flex', alignItems: 'center', minHeight: 57, opacity: frame >= starts[i] - 4 ? 1 : 0}}>
                  <span style={{color: theme.accent, marginRight: 18}}>$</span>
                  <span style={{color: theme.text}}>{c.slice(0, counts[i])}</span>
                  {typing === i ? <span style={{display: 'inline-block', width: 14, height: 30, marginLeft: 4, background: theme.accent, opacity: counts[i] >= c.length ? blink : 1}} /> : null}
                </div>
              ))}
            </div>
          </div>
        </div>
        <div style={{opacity: ramp(frame, 196, 24), transform: `translateY(${(1 - ramp(frame, 196, 24)) * 16}px)`}}>
          <div style={{color: theme.accent, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(40, theme), letterSpacing: '0.2em'}}>{d.closing}</div>
          <div style={{display: 'inline-block', marginTop: 14, paddingTop: 16, borderTop: `2px dashed ${theme.muted}`, color: theme.muted, fontSize: size(30, theme)}}>{d.note}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type Props = {headline: string; data: {subtitle: string; pills: string[]; tag: string}; theme: Record<string, any>};

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 14, 14));
  const pulse = 0.5 + 0.5 * Math.sin(frame / 38);
  const line = ramp(frame, 0, 26);
  const letters = props.headline.split('');
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', justifyContent: 'center', opacity: fade}}>
      <div style={{position: 'absolute', left: 40, top: 140, width: 1100, height: 800, background: `radial-gradient(closest-side, ${theme.accent}, transparent)`, opacity: (0.05 + 0.07 * pulse) * ramp(frame, 10, 60)}} />
      <div style={{width: 320 * line, height: 4, background: theme.accent, borderRadius: theme.radius, marginBottom: 36}} />
      <h1 style={{margin: 0, display: 'flex', fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(168, theme), letterSpacing: '-0.02em', lineHeight: 1, color: theme.text}}>
        {letters.map((ch, i) => {
          const p = ramp(frame, 22 + i * 3, 22);
          return <span key={i} style={{display: 'inline-block', opacity: p, transform: `translateY(${(1 - p) * 28}px)`}}>{ch}</span>;
        })}
      </h1>
      <p style={{margin: '28px 0 0', color: theme.body, fontSize: size(48, theme), ...enterStyle(progress(frame, fps, theme, 5), theme)}}>{props.data.subtitle}</p>
      <div style={{display: 'flex', gap: 24, marginTop: 56}}>
        {props.data.pills.map((pill, i) => {
          const p = ramp(frame, 78 + i * 8, 20);
          return (
            <div key={i} style={{display: 'flex', alignItems: 'center', gap: 14, padding: '14px 30px', borderRadius: 999, border: `2px solid ${theme.muted}`, fontSize: size(30, theme), color: theme.text, opacity: p, transform: `translateY(${(1 - p) * 24}px)`}}>
              <span style={{width: 10, height: 10, borderRadius: 5, background: theme.accent}} />
              {pill}
            </div>
          );
        })}
      </div>
      <div style={{position: 'absolute', left: 120, bottom: 90, padding: '6px 18px', border: `2px dashed ${theme.muted}`, borderRadius: theme.radius, color: theme.muted, fontFamily: 'monospace', fontSize: size(28, theme), opacity: ramp(frame, 120, 20)}}>{props.data.tag}</div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type NodeDef = {label: string; mono?: boolean};
type Props = {headline: string; data: {nodes: NodeDef[]; branch: string[]; optional: string; interrupt: string; caption: string}; theme: Record<string, any>};
type Th = Record<string, any>;

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));

const Chevron = (p: {x: number; y: number; dir: string; theme: Th; o: number}) => {
  const d = p.dir === 'd' ? `M${p.x - 9},${p.y - 11} L${p.x},${p.y} L${p.x + 9},${p.y - 11}` : `M${p.x - 11},${p.y - 9} L${p.x},${p.y} L${p.x - 11},${p.y + 9}`;
  return <path d={d} fill='none' stroke={p.theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={p.o} />;
};

const Box = (p: {x: number; y: number; w: number; h: number; label: string; t: number; active: number; theme: Th; fs: number; mono?: boolean; dashed?: boolean; split?: boolean}) => {
  const cut = p.label.indexOf(' ');
  const lines = p.split && cut > 0 ? [p.label.slice(0, cut), p.label.slice(cut + 1)] : [p.label];
  const dash = p.dashed ? '8 8' : undefined;
  return (
    <g opacity={p.t} transform={`translate(0 ${(1 - p.t) * 20})`}>
      <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={14} fill={p.theme.background} stroke={p.theme.muted} strokeWidth={2} strokeDasharray={dash} />
      <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={14} fill='none' stroke={p.theme.accent} strokeWidth={3} strokeDasharray={dash} opacity={p.active} />
      {lines.map((l, i) => (
        <text key={i} x={p.x + p.w / 2} y={p.y + p.h / 2 + (i - (lines.length - 1) / 2) * (p.fs + 6) + p.fs * 0.35} textAnchor='middle' fontSize={p.fs} fill={p.theme.text} fontFamily={p.mono ? 'monospace' : p.theme.font_body}>{l}</text>
      ))}
    </g>
  );
};

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 14, 14));
  const W = 1680, NW = 252, NH = 110, GAP = (W - 6 * NW) / 5, RY = 70, CY = RY + NH / 2;
  const cx = (i: number) => i * (NW + GAP) + NW / 2;
  const D0 = 30, SPAN = 200;
  const tAt = (x: number) => D0 + (SPAN * (x - cx(0))) / (cx(5) - cx(0));
  const dotX = interpolate(frame, [D0, D0 + SPAN], [cx(0), cx(5)], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const nodeT = (i: number) => (i === 0 ? ramp(frame, 6, 20) : ramp(frame, tAt(cx(i) - NW / 2) - 22, 20));
  const nodeA = (i: number) => clamp01((dotX - (cx(i) - NW / 2)) / 30);
  const dotO = ramp(frame, D0 - 8, 8);
  const pulse = 0.5 + 0.5 * Math.sin(frame / 8);
  const c3 = cx(3), LY = 260, LH = 100, LC = LY + LH / 2;
  const stem = ramp(frame, 150, 22);
  const oX = c3 - 100, cX = c3 + 140, cW = 280, mX = cX + cW + 40;
  const c1 = ramp(frame, 188, 12), c2 = ramp(frame, 214, 12);
  const iX = c3 - 420, iW = 280;
  const bl = d.branch;
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{flex: 1, display: 'flex', alignItems: 'center'}}>
        <svg width={W} height={500} viewBox={`0 0 ${W} 500`}>
          <path d={`M${cx(5)},${RY} V28 H${cx(0)} V${RY}`} fill='none' stroke={theme.muted} strokeWidth={2} strokeDasharray='10 10' opacity={0.8 * ramp(frame, 250, 24)} />
          <Chevron x={cx(0)} y={RY - 4} dir='d' theme={theme} o={ramp(frame, 270, 10)} />
          <text x={W / 2} y={38} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} stroke={theme.background} strokeWidth={26} paintOrder='stroke' opacity={ramp(frame, 266, 20)}>{d.interrupt}</text>
          {d.nodes.map((n, i) => (
            <Box key={i} x={cx(i) - NW / 2} y={RY} w={NW} h={NH} label={n.label} mono={n.mono} t={nodeT(i)} active={nodeA(i)} theme={theme} fs={size(32, theme)} />
          ))}
          {d.nodes.slice(0, -1).map((n, i) => {
            const x1 = cx(i) + NW / 2, x2 = cx(i + 1) - NW / 2;
            const fr = clamp01((dotX - x1) / (x2 - x1));
            return (
              <g key={i}>
                <line x1={x1} y1={CY} x2={x2} y2={CY} stroke={theme.muted} strokeWidth={2} opacity={0.4 * nodeT(i + 1)} />
                <line x1={x1} y1={CY} x2={x1 + (x2 - x1) * fr} y2={CY} stroke={theme.accent} strokeWidth={3} />
                <Chevron x={x2} y={CY} dir='r' theme={theme} o={fr >= 1 ? 1 : 0} />
              </g>
            );
          })}
          <circle cx={dotX} cy={CY} r={22 + 4 * pulse} fill={theme.accent} opacity={0.22 * dotO} />
          <circle cx={dotX} cy={CY} r={9} fill={theme.accent} opacity={dotO} />
          <line x1={c3} y1={RY + NH} x2={c3} y2={RY + NH + (LY - RY - NH) * stem} stroke={theme.accent} strokeWidth={3} />
          <path d={`M${c3},220 H${iX + iW / 2} V${LY}`} fill='none' stroke={theme.muted} strokeWidth={2} strokeDasharray='8 8' opacity={ramp(frame, 176, 24)} />
          <Box x={iX} y={LY} w={iW} h={LH} label={d.optional} t={ramp(frame, 184, 22)} active={0} theme={theme} fs={size(28, theme)} dashed split />
          <Box x={oX} y={LY} w={200} h={LH} label={bl[0]} t={ramp(frame, 166, 20)} active={stem >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} />
          <line x1={oX + 200} y1={LC} x2={oX + 200 + 40 * c1} y2={LC} stroke={theme.accent} strokeWidth={3} />
          <Chevron x={oX + 240} y={LC} dir='r' theme={theme} o={c1 >= 1 ? 1 : 0} />
          <Box x={cX} y={LY} w={cW} h={LH} label={bl[1]} t={ramp(frame, 196, 20)} active={c1 >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} split />
          <line x1={cX + cW} y1={LC} x2={cX + cW + 40 * c2} y2={LC} stroke={theme.accent} strokeWidth={3} />
          <Chevron x={mX} y={LC} dir='r' theme={theme} o={c2 >= 1 ? 1 : 0} />
          <Box x={mX} y={LY} w={200} h={LH} label={bl[2]} t={ramp(frame, 224, 20)} active={c2 >= 1 ? 1 : 0} theme={theme} fs={size(30, theme)} />
          <text x={0} y={470} fontSize={size(30, theme)} fill={theme.muted} opacity={ramp(frame, 300, 24)}>{d.caption}</text>
        </svg>
      </div>
    </AbsoluteFill>
  );
}

