      <div style={{flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', gap: 56}}>
        <div style={{display: 'flex', alignItems: 'center'}}>
          <Card card={d.surface} t0={10} frame={frame} theme={theme} />
          <svg width={560} height={340} viewBox='0 0 560 340'>
            <line x1={30} y1={120} x2={30 + 500 * a1} y2={120} stroke={theme.accent} strokeWidth={3} />
            <path d='M519,109 L530,120 L519,131' fill='none' stroke={theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={a1 >= 1 ? 1 : 0} />
            <text x={280} y={90} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} opacity={ramp(frame, 76, 20)}>{d.down}</text>
            <line x1={530} y1={240} x2={530 - 500 * a2} y2={240} stroke={theme.accent} strokeWidth={3} />
            <path d='M41,229 L30,240 L41,251' fill='none' stroke={theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={a2 >= 1 ? 1 : 0} />
            <text x={280} y={290} textAnchor='middle' fontSize={size(28, theme)} fill={theme.body} opacity={ramp(frame, 104, 20)}>{d.up}</text>
          </svg>
          <Card card={d.brain} t0={30} frame={frame} theme={theme} />
        </div>
        <div style={{position: 'relative', display: 'flex', width: 840, height: 110, boxSizing: 'border-box', border: `2px solid ${theme.muted}`, borderRadius: 55, opacity: ramp(frame, 130, 20)}}>
          <div style={{position: 'absolute', top: 5, left: 5 + 414 * slide, width: 414, height: 96, boxSizing: 'border-box', border: `3px solid ${theme.accent}`, borderRadius: 48, overflow: 'hidden'}}>
            <div style={{position: 'absolute', inset: 0, background: theme.accent, opacity: 0.14}} />
          </div>
          {d.modes.map((m, i) => (
            <div key={i} style={{position: 'relative', flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center'}}>
              <div style={{fontFamily: 'monospace', fontSize: size(30, theme), color: theme.text}}>{m.name}</div>
              <div style={{fontSize: size(28, theme), color: theme.muted}}>{m.note}</div>
            </div>
          ))}
        </div>
        <div style={{display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 16, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(60, theme), letterSpacing: '-0.02em'}}>
          {words.map((w, i) => {
            const q = ramp(frame, 190 + i * 4, 16);
            const hot = w.replace(/[.,!?]/g, '') === d.emphasis;
            return <span key={i} style={{color: hot ? theme.accent : theme.text, opacity: q, transform: `translateY(${(1 - q) * 18}px)`}}>{w}</span>;
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type Th = Record<string, any>;
type Props = {headline: string; data: {rows: string[]; commands: string[]; closing: string; note: string}; theme: Th};

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

const Lock = (p: {c: number; theme: Th}) => (
  <svg width={64} height={84} viewBox='0 0 64 84'>
    <path d='M18,42 V30 a14,14 0 0 1 28,0 V42' transform={`translate(0 ${-14 * (1 - p.c)})`} fill='none' stroke={p.c > 0.5 ? p.theme.accent : p.theme.muted} strokeWidth={4} strokeLinecap='round' />
    <rect x={8} y={42} width={48} height={34} rx={6} fill='none' stroke={p.theme.text} strokeWidth={3} />
    <circle cx={32} cy={59} r={4.5} fill={p.theme.accent} opacity={p.c} />
  </svg>
);

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 8), 1 - ramp(frame, durationInFrames - 30, 30));
  const starts = [58, 98];
  const counts = d.commands.map((c, i) => Math.max(0, Math.min(c.length, Math.floor((frame - starts[i]) * 1.5))));
  const typing = counts[1] > 0 ? 1 : 0;
  const blink = frame % 30 < 18 ? 1 : 0;
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 64}}>
        <div style={{display: 'flex', gap: 60, alignItems: 'center'}}>
          <div style={{width: 820, display: 'flex', flexDirection: 'column', gap: 28}}>
            {d.rows.map((r, i) => {
              const t = ramp(frame, 10 + i * 14, 20);
              const c = ramp(frame, 30 + i * 14, 14);
              return (
                <div key={i} style={{display: 'flex', alignItems: 'center', gap: 32, padding: '20px 32px', border: `2px solid ${theme.muted}`, borderRadius: 14, fontSize: size(38, theme), opacity: t, transform: `translateX(${(1 - t) * -28}px)`}}>
                  <Lock c={c} theme={theme} />
                  {r}
                </div>
              );
            })}
          </div>
          <div style={{width: 800, boxSizing: 'border-box', border: `2px solid ${theme.muted}`, borderRadius: 14, overflow: 'hidden', opacity: ramp(frame, 34, 22), transform: `translateY(${(1 - ramp(frame, 34, 22)) * 24}px)`}}>
            <div style={{display: 'flex', gap: 10, padding: '16px 22px', borderBottom: `2px solid ${theme.muted}`}}>
              {[0, 1, 2].map((k) => <span key={k} style={{width: 14, height: 14, borderRadius: 7, background: theme.muted, opacity: 0.6}} />)}
            </div>
            <div style={{padding: '36px 36px 44px', fontFamily: 'monospace', fontSize: size(30, theme), lineHeight: 1.9}}>
              {d.commands.map((c, i) => (
                <div key={i} style={{display: 'flex', alignItems: 'center', minHeight: 57, opacity: frame >= starts[i] - 4 ? 1 : 0}}>
                  <span style={{color: theme.accent, marginRight: 18}}>$</span>
                  <span style={{color: theme.text}}>{c.slice(0, counts[i])}</span>
                  {typing === i ? <span style={{display: 'inline-block', width: 14, height: 30, marginLeft: 4, background: theme.accent, opacity: counts[i] >= c.length ? blink : 1}} /> : null}
                </div>
              ))}
            </div>
          </div>
        </div>
        <div style={{opacity: ramp(frame, 196, 24), transform: `translateY(${(1 - ramp(frame, 196, 24)) * 16}px)`}}>
          <div style={{color: theme.accent, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(40, theme), letterSpacing: '0.2em'}}>{d.closing}</div>
          <div style={{display: 'inline-block', marginTop: 14, paddingTop: 16, borderTop: `2px dashed ${theme.muted}`, color: theme.muted, fontSize: size(30, theme)}}>{d.note}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
